    public static function has(?string $key): bool
    {
        return $key !== null && isset(self::ALL[$key]);
    }

    // Inline <svg>; an unknown key draws the "all" grid so a menu entry never ends up empty
    public static function svg(?string $key, string $class = 'ss-icon'): string
    {
        $inner = (self::ALL[$key] ?? self::ALL['all'])[1];

        return '<svg class="' . e($class) . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
            . ' stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $inner . '</svg>';
    }

    public static function ui(string $name, string $class = 'ss-ui'): string
    {
        return '<svg class="' . e($class) . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
            . ' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . (self::UI[$name] ?? '') . '</svg>';
    }

    // A Font Awesome icon the size and place of the <i class="fab fa-..."> it replaces: 1em tall, as wide as
    // the glyph, sitting on the text baseline (.ss-fa in resources/assets/css/ss.css)
    public static function fa(string $name, string $class = '', string $style = ''): string
    {
        [$width, $path] = self::FA[$name];

        return '<svg class="ss-fa' . ($class !== '' ? ' ' . e($class) : '') . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' . $width . ' 512"'
            . ' width="' . round($width / 512, 4) . 'em" height="1em" fill="currentColor" aria-hidden="true" focusable="false"'
            . ($style !== '' ? ' style="' . e($style) . '"' : '') . '><path d="' . $path . '"/></svg>';
    }

    // [key => label], for the admin's icon list
    public static function options(): array
    {
        return array_map(fn ($icon) => $icon[0], self::ALL);
    }
}
